optimist.raw:
{
  "stance": "I use modestly lenient portfolio assumptions because the synthetic score is only a susceptibility proxy, not measured flood depth; for the offer I credit its mostly dry mapped tiers but stay cautious where basements, protection details, and coverage are unknown.",
  "parameters": [
    {
      "name": "depthScaleM",
      "reason": "The score is a 0 to 1 susceptibility proxy, not measured depth, and the widest tier affects 259 of 600 buildings. I choose below the 4 m reference because the evidence does not establish deep water.",
      "basis": "data_profile",
      "value": 3
    },
    {
      "name": "fragility.informal_iron_sheet",
      "reason": "Informal iron-sheet buildings are 29.8% of buildings but only 0.3% of insured value, so a modest vulnerability uplift is defensible without making it extreme.",
      "basis": "data_profile",
      "value": 1.3
    },
    {
      "name": "fragility.semi_permanent",
      "reason": "Semi-permanent buildings are 30.2% of buildings and 1.3% of value; I retain an uplift but reduce the 1.2 reference slightly given their small value share.",
      "basis": "data_profile",
      "value": 1.1
    },
    {
      "name": "fragility.permanent_masonry",
      "reason": "Permanent masonry represents 13.3% of insured value, and the JRC curve is residential rather than locally calibrated. A small reduction from the neutral factor is cautious leniency.",
      "basis": "jrc_reference",
      "value": 0.9
    },
    {
      "name": "fragility.concrete_rcc",
      "reason": "Concrete RCC holds 85.1% of insured value, making this class important, but the JRC residential curve provides no Kenya-specific construction adjustment. I use a modest reduction from 0.7.",
      "basis": "data_profile",
      "value": 0.65
    },
    {
      "name": "cap.informal_iron_sheet",
      "reason": "The class contributes only 0.3% of portfolio value, supporting a cap below the 0.95 reference while retaining substantial possible damage.",
      "basis": "data_profile",
      "value": 0.9
    },
    {
      "name": "cap.semi_permanent",
      "reason": "Semi-permanent buildings account for 1.3% of insured value; a somewhat lower cap than the 0.9 reference limits severity without assuming negligible damage.",
      "basis": "data_profile",
      "value": 0.85
    },
    {
      "name": "cap.permanent_masonry",
      "reason": "Masonry accounts for 13.3% of insured value, and the JRC curve reaches 1 at 6 m. I retain a high cap but set it slightly below the 0.85 reference.",
      "basis": "jrc_reference",
      "value": 0.8
    },
    {
      "name": "cap.concrete_rcc",
      "reason": "Concrete RCC accounts for 85.1% of value, so a cap far below the reference would be hard to defend despite its construction type.",
      "basis": "data_profile",
      "value": 0.78
    },
    {
      "name": "returnPeriods.extreme",
      "reason": "The data profile has no fixed return periods for its nested score tiers. I retain the 10-year reference rather than infer calibrated frequency from a proxy.",
      "basis": "judgement",
      "value": 10
    },
    {
      "name": "returnPeriods.severe",
      "reason": "The severe tier has no fixed return period, so the 25-year reference is a transparent assumption and remains above the extreme tier.",
      "basis": "judgement",
      "value": 25
    },
    {
      "name": "returnPeriods.moderate",
      "reason": "The moderate tier has no fixed recurrence estimate; I keep the 50-year reference, strictly above severe.",
      "basis": "judgement",
      "value": 50
    },
    {
      "name": "returnPeriods.occasional",
      "reason": "No fixed return period is supplied for occasional, so I retain the 100-year reference and preserve the required tier order.",
      "basis": "judgement",
      "value": 100
    },
    {
      "name": "returnPeriods.common",
      "reason": "Common is the widest and rarest footprint, but the score does not calibrate its frequency. I keep the 250-year reference rather than claim greater rarity.",
      "basis": "judgement",
      "value": 250
    },
    {
      "name": "offer.bufferRadiusM",
      "reason": "The location is approximate=false and the stated buffer is 250 m; mapped depth is zero within that buffer through occasional, but rises to about 0.194 m in common. I retain 250 m rather than discard nearby water.",
      "basis": "offer",
      "value": 250
    },
    {
      "name": "offer.ingressThresholdM",
      "reason": "The offer has two basements and critical plant in B1, while barriers and non-return valves are not stated. I keep the 0.1 m reference because protection against ingress is unknown.",
      "basis": "offer",
      "value": 0.1
    },
    {
      "name": "offer.basementDamageExtreme",
      "reason": "Critical plant is in B1, but the mapped point, buffer, and ponding depths are zero in this tier; the 0.15 reference is a restrained starting rung.",
      "basis": "offer",
      "value": 0.15
    },
    {
      "name": "offer.basementDamageSevere",
      "reason": "The next rung rises modestly from 0.15 because two basement levels and plant in B1 are documented, while pump backup and barriers are unknown.",
      "basis": "offer",
      "value": 0.25
    },
    {
      "name": "offer.basementDamageModerate",
      "reason": "The offer states six items of equipment below ground and critical plant in B1, supporting the reference 0.4 rung despite zero mapped water at this tier.",
      "basis": "offer",
      "value": 0.4
    },
    {
      "name": "offer.basementDamageOccasional",
      "reason": "Drains are overloaded at this tier and the offer has two basements; the 0.55 reference rung reflects greater damage potential without assuming undocumented protection.",
      "basis": "offer",
      "value": 0.55
    },
    {
      "name": "offer.basementDamageCommon",
      "reason": "The common-tier buffer depth is about 0.194 m and drains are overloaded, while critical plant is below ground and pump backup is unknown. I retain the 0.7 reference as the rarest rung.",
      "basis": "offer",
      "value": 0.7
    },
    {
      "name": "offer.belowGroundShare",
      "reason": "The document gives valueBelowGroundKes as null, so the below-ground value is unknown; I use the 0.08 reference rather than treat missing information as zero.",
      "basis": "offer",
      "value": 0.08
    },
    {
      "name": "offer.outageDaysExtreme",
      "reason": "BI coverage is not stated, so this rung has no effect here; I retain the 2-day reference rather than infer that coverage is absent.",
      "basis": "offer",
      "value": 2
    },
    {
      "name": "offer.outageDaysSevere",
      "reason": "BI coverage is not stated, so this rung has no effect here; I retain the 5-day reference, with no evidence for faster reopening.",
      "basis": "offer",
      "value": 5
    },
    {
      "name": "offer.outageDaysModerate",
      "reason": "BI coverage is not stated, so this rung has no effect here; the 10-day reference is retained because critical plant is in B1 and pump backup is unknown.",
      "basis": "offer",
      "value": 10
    },
    {
      "name": "offer.outageDaysOccasional",
      "reason": "BI coverage is not stated, so this rung has no effect here; I keep the 20-day reference because the offer lists basement plant and overloaded drains in this tier.",
      "basis": "offer",
      "value": 20
    },
    {
      "name": "offer.outageDaysCommon",
      "reason": "BI coverage is not stated, so this rung has no effect here; I retain the 40-day reference because the offer documents critical basement plant and does not state pump backup.",
      "basis": "offer",
      "value": 40
    },
    {
      "name": "offer.uncertaintyLoading",
      "reason": "The offer's drainage description does not establish protection from seepage, blocked drains, or pump failure, and pump backup is null. I retain the 0.1 reference rather than assume these causes are controlled.",
      "basis": "offer",
      "value": 0.1
    }
  ]
}
